import{_ as o,o as t,c as l,a2 as d}from"./chunks/framework.BUwdTBzS.js";const u=JSON.parse('{"title":"按需-更新日志编写规范","description":"更新日志（changelog）条目的编写规范（概括式、同源合并、破坏性变更保留必要信息）。撰写或修订更新日志时加载。","frontmatter":{"title":"按需-更新日志编写规范","description":"更新日志（changelog）条目的编写规范（概括式、同源合并、破坏性变更保留必要信息）。撰写或修订更新日志时加载。"},"headers":[],"relativePath":"rules/按需-更新日志编写规范.md","filePath":"rules/按需-更新日志编写规范.md","lastUpdated":null}'),i={name:"rules/按需-更新日志编写规范.md"};function a(c,e,r,n,s,h){return t(),l("div",null,[...e[0]||(e[0]=[d('<blockquote><p>📄 本页由源文件 <code>rules/按需-更新日志编写规范.mdc</code> 自动投影生成（单一权威源）。请勿直接编辑本页。</p></blockquote><h1 id="按需-更新日志编写规范" tabindex="-1">按需-更新日志编写规范 <a class="header-anchor" href="#按需-更新日志编写规范" aria-label="Permalink to &quot;按需-更新日志编写规范&quot;">​</a></h1><blockquote><p>触发时机：撰写或修订项目 <code>changelog.md</code>（或同类版本更新说明）时。 核心：日志面向<strong>使用者</strong>，只回答「哪个组件、发生了什么、我要不要动代码」。</p></blockquote><hr><h2 id="_1-描述方式-概括式" tabindex="-1">1. 描述方式：概括式 <a class="header-anchor" href="#_1-描述方式-概括式" aria-label="Permalink to &quot;1. 描述方式：概括式&quot;">​</a></h2><ul><li><strong>一条一句话</strong>，只写「改了什么 + 影响」；根因、算法、实现手段不写进日志</li><li>「一句话」指<strong>概括方式</strong>（不展开根因与实现细节），不是「一句里塞多件事」—— 一条只讲一个主题</li><li>❌ <code>定位尺寸改用 offsetWidth / offsetHeight，因为 transform 会让 getBoundingClientRect 返回缩放后的视觉尺寸</code></li><li>✅ <code>修复缩放动画期间位置错位</code></li><li>根因、取舍与实现细节归 commit message / PR 描述</li><li><strong>边界</strong>：「实现细节」指内部构建 / 脚本 / 测试 / 重构等使用者不可感知的改动；<strong><code>docs/</code> 与 <code>development/</code> 的内容更新不属于此列，必须入日志</strong>（写法见 §2、§3）</li></ul><h2 id="_2-合并同源、拆开异源" tabindex="-1">2. 合并同源、拆开异源 <a class="header-anchor" href="#_2-合并同源、拆开异源" aria-label="Permalink to &quot;2. 合并同源、拆开异源&quot;">​</a></h2><ul><li>同一组件、同一工具函数族、同一能力主题的多个改动 → 合并为一条</li><li>❌ Tooltip 定位一条 + Tooltip 交互一条</li><li>✅ Tooltip 定位与交互合并为一条</li><li>❌ 一条里混入多个<strong>不相关主题</strong>（如「新增属性 + 修复失焦 + 构建产物调整」）—— 读者无法判断其中哪句与自己相关</li><li>合并的对象是「同源改动」，不是「为控制条数而压缩」；不同源就拆开，宁可条数多也不要堆叠</li><li>无信息量的兜底条目（如「组件库及文档代码优化」）不写 —— 但<strong>不是省略文档更新</strong>：<code>docs/</code>（面向使用者）与 <code>development/</code>（面向贡献者）的<strong>内容更新都要入日志</strong>，需写明「哪篇 / 哪份说明变了、变成什么」；受众不同的文档更新各自成条（如使用者文档 <code>docs/</code>＋<code>README</code> 一条、贡献者文档 <code>development/</code>＋<code>CONTRIBUTING</code> 一条），禁止的只是「优化文档」这类一句打包写法</li></ul><h2 id="_3-保留必要信息-不得过度概括" tabindex="-1">3. 保留必要信息（不得过度概括） <a class="header-anchor" href="#_3-保留必要信息-不得过度概括" aria-label="Permalink to &quot;3. 保留必要信息（不得过度概括）&quot;">​</a></h2><p>以下必须写清，压缩到看不出影响即不合格：</p><table tabindex="0"><thead><tr><th>场景</th><th>要求</th></tr></thead><tbody><tr><td>破坏性变更</td><td>保留 <code>⚠️ **破坏性变更**</code> 前缀，写明「移除了什么 / 改用什么」</td></tr><tr><td>默认值变化</td><td>写明旧值 → 新值</td></tr><tr><td>需用户改代码</td><td>写明替代写法</td></tr><tr><td>文档更新</td><td><code>docs/</code> / <code>README</code> / <code>development/</code> / <code>CONTRIBUTING</code> 的内容更新须写明「哪篇文档变了、读者要注意什么」，按受众拆条；不写「优化文档」这类打包表述</td></tr></tbody></table><h2 id="_4-格式约定" tabindex="-1">4. 格式约定 <a class="header-anchor" href="#_4-格式约定" aria-label="Permalink to &quot;4. 格式约定&quot;">​</a></h2><ul><li>每条以动词开头：<code>新增</code> / <code>优化</code> / <code>增强</code> / <code>修复</code> / <code>重构</code></li><li>组件与工具函数名用 Markdown 链接指向文档，如 <code>[文字提示 Tooltip](/guide/components/tooltip.html)</code></li><li>属性名、API、全局对象等用行内代码包裹</li><li><strong>条目数不设上限</strong>：由改动量自然决定 —— 架构重构、批量破坏性变更的大版本条目自然多，小版本自然少</li><li><strong>不为凑数拆分</strong>（一件事写成多条），<strong>也不为控数堆叠或删减信息</strong>（多件事挤进一条、砍掉必要语义）</li><li>每条长度以「一句话可读」为准；若一条读下来需要逐句分辨主题，说明该拆条了</li></ul><h2 id="_5-版本与历史" tabindex="-1">5. 版本与历史 <a class="header-anchor" href="#_5-版本与历史" aria-label="Permalink to &quot;5. 版本与历史&quot;">​</a></h2><ul><li>已发布版本的历史条目<strong>默认不回改</strong>，用户明确要求时才回改</li><li>新版本严格按本规范撰写，不因历史风格而妥协</li></ul><h2 id="_6-自检清单" tabindex="-1">6. 自检清单 <a class="header-anchor" href="#_6-自检清单" aria-label="Permalink to &quot;6. 自检清单&quot;">​</a></h2><ul><li>[ ] 每条能否一句话说清「改了什么 + 影响」？</li><li>[ ] 同组件 / 同工具函数族 / 同能力主题的条目是否已合并？</li><li>[ ] 是否存在「一条堆叠多个不相关主题」的情况？应拆为多条</li><li>[ ] 破坏性变更、默认值变化是否写明替代用法？</li><li>[ ] 是否残留根因、算法、内部函数名等实现细节？</li><li>[ ] <code>docs/</code> / <code>README</code> / <code>development/</code> / <code>CONTRIBUTING</code> 的内容更新是否已入日志（按受众拆条，不是「优化文档」这类打包写法）？</li><li>[ ] 无信息量的条目是否已删除？</li><li>[ ] 是否为了控制条数而删减或模糊了必要信息？（条目数不是压缩目标）</li></ul>',17)])])}const g=o(i,[["render",a]]);export{u as __pageData,g as default};
